using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace ScreenCraft
{
    internal static class DailySurfaceTests
    {
        static void Click(Button button){typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        static void Preview(Control root,Bitmap image){using(var g=Graphics.FromImage(image))PreferencesPreview.Draw(g,root,root);}
        static System.Collections.Generic.IEnumerable<Control> Children(Control root){foreach(Control child in root.Controls){yield return child;foreach(var nested in Children(child))yield return nested;}}
        static Bitmap Image(){var image=new Bitmap(240,160);using(var g=Graphics.FromImage(image)){g.Clear(Color.White);g.FillRectangle(Brushes.Coral,30,30,130,70);}return image;}
        internal static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("daily pin project/rotated flipped project reopens in same direction without flattening annotations",delegate{using(var canvas=new Canvas(Image())){canvas.AddAnnotation(ScreenCraftTests.Mark(Tool.Arrow,25,25,200,110));using(var pin=PinWindow.CreateHidden(canvas.ExportDocument(),new Rectangle(0,0,1200,900))){pin.ChangeView(1,true,false);string path=Path.Combine(output,"pin-view-editable.sccraft");using(var project=pin.ExportDocument()){check(project.Shapes.Length==1,"flattened annotations");project.Save(path);}using(var reopened=PinWindow.CreateHidden(AnnotationDocument.Open(path),new Rectangle(0,0,1200,900)))using(var actual=reopened.ViewImage())using(var expected=pin.ViewImage()){check(reopened.State.QuarterTurns==1&&reopened.State.FlipX&&actual.Size==expected.Size,"project view metadata");check(actual.GetPixel(80,100)==expected.GetPixel(80,100),"view pixels");}}}});
            run("daily UI/pin manager routes restore and rotation without showing hidden pins",delegate{using(var pin=PinWindow.CreateHidden(AnnotationDocument.FromImage(Image()),new Rectangle(0,0,1200,900)))using(var manager=new PinManagerWindow()){pin.SetPinHidden(true);manager.Reload(true);int restored=0;manager.RestorePin=delegate(PinWindow p){check(p==pin,"wrong pin");p.State.HiddenByUser=false;restored++;};Click(Children(manager).OfType<CaptureIconButton>().Single(c=>c.AccessibleName=="恢复与定位"));Click(Children(manager).OfType<CaptureIconButton>().Single(c=>c.AccessibleName=="旋转 90°"));check(restored==1&&pin.State.QuarterTurns==1&&!manager.Visible&&!pin.Visible,"manager route or desktop boundary");using(var image=new Bitmap(manager.ClientSize.Width,manager.ClientSize.Height)){Preview(manager,image);image.Save(Path.Combine(output,"pin-manager-offscreen.png"));}}});
            run("daily UI/history copy pin and delete affect only selected generated record",delegate{string root=Path.Combine(output,"history-ui-"+Guid.NewGuid().ToString("N"));var store=new CaptureHistory(root);using(var image=Image())store.Record(image,10);using(var window=new HistoryWindow(root,true)){int copied=0,pinned=0;window.CopyImage=delegate(Bitmap image){check(image.Size==new Size(240,160),"copy size");copied++;};window.PinImage=delegate(Bitmap image){pinned++;image.Dispose();};var buttons=Children(window).OfType<PreferencesButton>().ToArray();Click(buttons.Single(c=>c.Text=="复制"));Click(buttons.Single(c=>c.Text=="贴图"));using(var image=new Bitmap(window.ClientSize.Width,window.ClientSize.Height)){Preview(window,image);image.Save(Path.Combine(output,"history-window-offscreen.png"));}Click(buttons.Single(c=>c.Text=="删除"));check(copied==1&&pinned==1&&store.List().Length==0&&!window.Visible,"history callbacks or boundary");}});
            run("daily UI/file editor mosaic control edits tile size and empty history reflects recording state",delegate{
                using(var editor=new CraftEditor(Image())){
                    editor.AnnotationCanvas.SetTool(Tool.Pixelate);
                    var size=Children(editor).OfType<CaptureSlider>().Single(control=>control.AccessibleName=="当前工具尺寸");
                    size.Value=29;
                    check(editor.AnnotationCanvas.DefaultStyle.MosaicBlock==29&&editor.AnnotationCanvas.DefaultStyle.Width!=29,"mosaic control changed pen width");
                }
                using(var history=new HistoryWindow(Path.Combine(output,"empty-history"),true)){
                    check(Children(history).OfType<Label>().Any(label=>label.Text.Contains("下次完成截图")),"empty message ignores recording preference");
                    check(!Children(history).OfType<Button>().Single(b=>b.Text=="清理历史").Enabled,"empty history allows clear");
                }
            });
            run("daily UI/local editor uses shared icon rows and keyboard mosaic mapping remains valid",delegate{using(var editor=new CraftEditor(Image())){editor.CreateControl();editor.PerformLayout();var controls=Children(editor).ToArray();check(!controls.OfType<ToolStrip>().Any(t=>!(t is StatusStrip)),"legacy text toolstrip remains");check(controls.OfType<CaptureIconButton>().Any(c=>c.AccessibleName=="标注")&&controls.OfType<CaptureIconButton>().Any(c=>c.AccessibleName=="点标注"),"annotation group modes");var method=typeof(CraftEditor).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic);var args=new object[]{new Message(),Keys.M};check((bool)method.Invoke(editor,args)&&editor.AnnotationCanvas.Tool==Tool.Pixelate,"mosaic key out of range");using(var image=new Bitmap(editor.ClientSize.Width,editor.ClientSize.Height)){Preview(editor,image);image.Save(Path.Combine(output,"local-editor-icons-offscreen.png"));}check(!editor.Visible&&editor.AnnotationCanvas.Height>500,"editor hidden or layout");}});
            run("daily lifecycle/path-specific exit events cannot target another portable directory",delegate{string a=InstallerCleanup.ExitEvent("fixture",Path.Combine(output,"Installed","ScreenCraft.exe")),b=InstallerCleanup.ExitEvent("fixture",Path.Combine(output,"Portable","ScreenCraft.exe"));check(a!=b&&a!=InstallerCleanup.ExitEvent("fixture",Path.Combine(output,"Installed","ScreenCraft.exe"),true),"exit event collision");check(InstallerCleanup.IsCommand(new[]{"--installer-request-exit"})&&!InstallerCleanup.IsCommand(new[]{"--background"}),"installer command routing");});
            run("daily transfer/file drag data contains real PNG and cleanup preserves unrelated files",delegate{string root=Path.Combine(output,"transfer-"+Guid.NewGuid().ToString("N"));string folder=Path.Combine(root,"Transfers");Directory.CreateDirectory(folder);string old=Path.Combine(folder,Guid.NewGuid().ToString("N")+".png"),manual=Path.Combine(folder,"manually-saved.png");File.WriteAllText(old,"old transfer");File.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddDays(-2));File.WriteAllText(manual,"user image");File.SetLastWriteTimeUtc(manual,DateTime.UtcNow.AddDays(-2));using(var image=Image()){string path;var data=ImageTransfer.Prepare(image,root,out path);check(data.GetDataPresent(DataFormats.FileDrop)&&((string[])data.GetData(DataFormats.FileDrop)).Single()==path&&File.Exists(path),"missing transfer payload");using(var loaded=System.Drawing.Image.FromFile(path))check(loaded.Size==image.Size,"PNG decode");check(!File.Exists(old)&&File.Exists(manual),"transfer cleanup boundaries");}});
            run("daily editor/clipboard failure preserves editor and copy-continue respects saved pin orientation",delegate{var doc=AnnotationDocument.FromImage(Image());doc.PinQuarterTurns=1;using(var editor=new CraftEditor(doc,null)){int errors=0,copies=0;editor.CopyOutput=delegate{throw new InvalidOperationException("fixture clipboard busy");};editor.CommandError=delegate{errors++;};var method=typeof(CraftEditor).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic);method.Invoke(editor,new object[]{new Message(),Keys.Control|Keys.C});check(errors==1&&!editor.IsDisposed,"copy failure closed editor");editor.CopyOutput=delegate(Bitmap image){check(image.Size==new Size(160,240),"pin view not applied to clipboard output");copies++;};method.Invoke(editor,new object[]{new Message(),Keys.Control|Keys.Shift|Keys.Enter});check(copies==1&&!editor.IsDisposed&&!editor.Visible,"copy-continue closed editor or used desktop");}});
            run("daily validation/corrupt appearance stays on disk and stale integer-overflow range is rejected",delegate{string root=Path.Combine(output,"daily-corrupt-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var store=new PreferenceStore(root);string bad="{\"Version\":1,\"PinOpacity\":3,\"PinRadius\":-50}";File.WriteAllText(store.FilePath,bad);var read=store.Load();check(read.PinOpacity==100&&store.Warning!=null&&File.ReadAllText(store.FilePath)==bad,"unsafe load or original removed");var desktop=new Rectangle(-1600,0,3520,1080);check(CaptureWorkflows.Resolve("repeat",desktop,desktop,Rectangle.Empty,new[]{0,0,int.MaxValue,100}).IsEmpty,"overflow accepted");check(StartupCommand.Matches(StartupCommand.For(Path.Combine(root,"ScreenCraft.exe")),Path.Combine(root,"ScreenCraft.exe"))&&!StartupCommand.Matches(StartupCommand.For(Path.Combine(root,"Other.exe")),Path.Combine(root,"ScreenCraft.exe")),"startup command matching");});
            run("daily rendering/owner-draw multirow lists retain all earlier rows",delegate{string root=Path.Combine(output,"history-multi-"+Guid.NewGuid().ToString("N"));var store=new CaptureHistory(root);using(var image=Image())for(int i=0;i<3;i++)store.Record(image,10);using(var window=new HistoryWindow(root,true)){var list=Children(window).OfType<ListBox>().Single();using(var image=new Bitmap(list.Width,list.ItemHeight*3))using(var g=Graphics.FromImage(image)){g.Clear(Color.White);var draw=typeof(ListBox).GetMethod("OnDrawItem",BindingFlags.Instance|BindingFlags.NonPublic);for(int i=0;i<3;i++)draw.Invoke(list,new object[]{new DrawItemEventArgs(g,list.Font,new Rectangle(0,i*list.ItemHeight,list.Width,list.ItemHeight),i,DrawItemState.None)});image.Save(Path.Combine(output,"history-three-rows.png"));for(int row=0;row<3;row++){int dark=0;for(int y=row*list.ItemHeight;y<(row+1)*list.ItemHeight;y++)for(int x=0;x<image.Width;x++){var pixel=image.GetPixel(x,y);if(pixel.R<150&&pixel.G<150&&pixel.B<150)dark++;}check(dark>80,"an earlier row was erased by a later row: "+row);}}}});
            run("daily export/PNG stream save and load survive a path longer than MAX_PATH",delegate{string folder=Path.Combine(output,"long-png");while(Path.GetFullPath(folder).Length<280)folder=Path.Combine(folder,"长路径-abcdefghij");FilePaths.EnsureDirectory(folder);string path=Path.Combine(folder,"建筑图片.png");using(var image=Image()){ImageFiles.SavePng(image,path);using(var loaded=CaptureHost.LoadFull(path))check(loaded.Size==image.Size&&loaded.GetPixel(60,60).ToArgb()==Color.Coral.ToArgb(),"long PNG pixels");}var preferences=new PreferenceStore(Path.Combine(folder,"Data"));preferences.Save(new Preferences{InitialTool="Arrow"});check(preferences.Load().InitialTool=="Arrow","long portable preferences");
                string annotation=Path.Combine(folder,"可编辑工程.sccraft");using(var document=AnnotationDocument.FromImage(Image()))document.Save(annotation);using(var document=AnnotationDocument.Open(annotation))check(document.Source.Size==new Size(240,160),"long annotation project");
                string boardPath=Path.Combine(folder,"参考画板.scboard");using(var document=new BoardDocument()){document.AddImage(Image(),PointF.Empty);document.Save(boardPath);}using(var document=BoardDocument.Open(boardPath))check(document.Items.Length==1,"long board project");
                check(FilePaths.Exists(path)&&Directory.GetFiles(FilePaths.Native(folder),"*.tmp").Length==0,"partial file left");
                File.WriteAllText(Path.Combine(output,"long-path-result.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{Kind="actual generated file integration; not desktop capture",PathLength=Path.GetFullPath(path).Length,MaxPath=260,PngAndEditableProjectsAndPreferences="PASS",SystemPolicyChanged=false}));
                using(var sample=CaptureHost.LoadFull(path))ImageFiles.SavePng(sample,Path.Combine(output,"long-path-sample.png"));});
        }
    }
}
